[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Student Performance Analytics Report — Bangladesh</title>
<style>
  :root {
    --primary: #1a3a5c;
    --accent: #2e86c1;
    --accent2: #27ae60;
    --warn: #e67e22;
    --danger: #c0392b;
    --light: #f4f8fb;
    --border: #d0dce8;
    --text: #1c2833;
    --muted: #5d7a8a;
    --card-bg: #ffffff;
    --excellent: #1a7a4a;
    --good: #2e86c1;
    --average: #e67e22;
    --poor: #c0392b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; background: #eef3f8; color: var(--text); line-height: 1.6; }
  .report-wrapper { max-width: 1200px; margin: 0 auto; padding: 20px; }

  /* Header */
  .report-header { background: linear-gradient(135deg, #0d2b4a 0%, #1a3a5c 60%, #2255a0 100%); color: white; border-radius: 12px; padding: 48px 40px 36px; margin-bottom: 28px; position: relative; overflow: hidden; }
  .report-header::after { content: ''; position: absolute; right: -40px; top: -40px; width: 300px; height: 300px; border-radius: 50%; background: rgba(255,255,255,0.04); }
  .report-header .flag { font-size: 32px; margin-bottom: 12px; }
  .report-header h1 { font-size: 2rem; font-weight: 700; line-height: 1.2; margin-bottom: 10px; }
  .report-header .subtitle { font-size: 1rem; opacity: 0.8; margin-bottom: 16px; }
  .report-meta { display: flex; gap: 24px; flex-wrap: wrap; font-size: 0.82rem; opacity: 0.7; margin-top: 8px; }
  .report-meta span::before { content: '• '; }

  /* Section layout */
  .section { background: var(--card-bg); border-radius: 10px; padding: 32px; margin-bottom: 24px; border: 1px solid var(--border); box-shadow: 0 2px 8px rgba(0,0,0,0.04); }
  .section-title { font-size: 1.25rem; font-weight: 700; color: var(--primary); border-bottom: 3px solid var(--accent); padding-bottom: 10px; margin-bottom: 24px; display: flex; align-items: center; gap: 10px; }
  .section-title .icon { width: 28px; height: 28px; background: var(--accent); border-radius: 6px; display: flex; align-items: center; justify-content: center; color: white; font-size: 14px; flex-shrink: 0; }
  .subsection { margin-top: 28px; }
  .subsection-title { font-size: 1rem; font-weight: 600; color: var(--primary); margin-bottom: 14px; padding-left: 10px; border-left: 3px solid var(--accent2); }

  /* KPI Cards */
  .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 16px; margin-bottom: 8px; }
  .kpi-card { background: var(--light); border-radius: 10px; padding: 20px 18px; border: 1px solid var(--border); position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; background: var(--accent); }
  .kpi-card.green::before { background: var(--accent2); }
  .kpi-card.orange::before { background: var(--warn); }
  .kpi-card.red::before { background: var(--danger); }
  .kpi-card.teal::before { background: #1abc9c; }
  .kpi-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.8px; color: var(--muted); margin-bottom: 6px; font-weight: 600; }
  .kpi-value { font-size: 2.1rem; font-weight: 800; color: var(--primary); line-height: 1; }
  .kpi-value.green { color: var(--accent2); }
  .kpi-value.orange { color: var(--warn); }
  .kpi-value.red { color: var(--danger); }
  .kpi-value.teal { color: #16a085; }
  .kpi-unit { font-size: 0.85rem; color: var(--muted); margin-top: 4px; }
  .kpi-badge { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 0.72rem; font-weight: 700; margin-top: 6px; }
  .badge-good { background: #d4efdf; color: #1a7a4a; }
  .badge-warn { background: #fdebd0; color: #a04000; }
  .badge-neutral { background: #d6eaf8; color: #154360; }
  .badge-teal { background: #d1f2eb; color: #0e6655; }

  /* Data tables */
  table { width: 100%; border-collapse: collapse; font-size: 0.88rem; }
  th { background: var(--primary); color: white; padding: 10px 12px; text-align: left; font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.5px; }
  td { padding: 9px 12px; border-bottom: 1px solid #eaecee; }
  tr:nth-child(even) td { background: #f8fafc; }
  tr:hover td { background: #eaf3fb; }
  .rank-1 td:first-child { font-weight: 700; color: var(--accent2); }
  .rank-badge { display: inline-block; width: 22px; height: 22px; border-radius: 50%; background: var(--accent); color: white; font-size: 0.72rem; font-weight: 700; text-align: center; line-height: 22px; margin-right: 6px; }

  /* Bar charts (SVG-based) */
  .chart-container { margin: 16px 0; }
  .chart-label { font-size: 0.8rem; color: var(--muted); text-align: center; margin-top: 6px; }

  /* Inline bar indicators */
  .bar-row { display: flex; align-items: center; gap: 10px; margin: 5px 0; }
  .bar-row .label { width: 120px; font-size: 0.82rem; color: var(--text); text-align: right; flex-shrink: 0; }
  .bar-row .bar-track { flex: 1; height: 14px; background: #e8eff5; border-radius: 7px; overflow: hidden; }
  .bar-row .bar-fill { height: 100%; border-radius: 7px; background: var(--accent); transition: width 0.3s; }
  .bar-row .bar-fill.green { background: var(--accent2); }
  .bar-row .bar-fill.orange { background: var(--warn); }
  .bar-row .bar-fill.purple { background: #8e44ad; }
  .bar-row .val { font-size: 0.78rem; color: var(--muted); width: 44px; flex-shrink: 0; }

  /* 2-col grid */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  @media (max-width: 760px) { .two-col { grid-template-columns: 1fr; } }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
  @media (max-width: 900px) { .three-col { grid-template-columns: 1fr 1fr; } }

  /* Insight boxes */
  .insight { background: #eaf5fe; border-left: 4px solid var(--accent); padding: 12px 16px; border-radius: 0 8px 8px 0; margin: 14px 0; font-size: 0.88rem; color: #1a3a5c; }
  .insight.green { background: #eafaf1; border-color: var(--accent2); color: #145a32; }
  .insight.orange { background: #fef9e7; border-color: var(--warn); color: #784212; }
  .insight.red { background: #fdedec; border-color: var(--danger); color: #7b241c; }

  /* Pill badges for performance */
  .pill { display: inline-block; padding: 2px 10px; border-radius: 10px; font-size: 0.75rem; font-weight: 700; }
  .pill-exc { background: #d4efdf; color: #1a7a4a; }
  .pill-good { background: #d6eaf8; color: #154360; }
  .pill-avg { background: #fdebd0; color: #a04000; }
  .pill-poor { background: #fdedec; color: #7b241c; }

  /* Heatmap grid */
  .heatmap-grid { display: grid; gap: 3px; }
  .heatmap-cell { padding: 8px 4px; border-radius: 4px; text-align: center; font-size: 0.75rem; font-weight: 600; }

  /* Progress bar for GPA trend */
  .gpa-progression { display: flex; align-items: center; gap: 0; margin: 12px 0; }
  .gpa-stage { flex: 1; text-align: center; }
  .gpa-stage .stage-val { font-size: 1.4rem; font-weight: 700; color: var(--primary); }
  .gpa-stage .stage-label { font-size: 0.72rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.5px; }
  .gpa-arrow { font-size: 1.5rem; color: var(--accent); padding: 0 8px; }
  .gpa-arrow.up { color: var(--accent2); }
  .gpa-arrow.down { color: var(--danger); }

  /* Scatter-like dot display */
  .dot-legend { display: flex; gap: 16px; font-size: 0.78rem; color: var(--muted); margin-top: 8px; flex-wrap: wrap; }
  .dot-legend span::before { content: '●'; margin-right: 4px; }

  /* Recommendations */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
  .rec-card { border-radius: 10px; padding: 20px; border: 1px solid var(--border); background: var(--light); }
  .rec-card .rec-num { font-size: 2rem; font-weight: 900; color: var(--accent); opacity: 0.3; line-height: 1; }
  .rec-card h4 { font-size: 0.95rem; font-weight: 700; color: var(--primary); margin: 4px 0 8px; }
  .rec-card p { font-size: 0.85rem; color: var(--muted); line-height: 1.5; }
  .rec-tag { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 0.7rem; font-weight: 700; background: #d6eaf8; color: #154360; margin-bottom: 8px; }
  .rec-tag.policy { background: #fdebd0; color: #a04000; }
  .rec-tag.school { background: #d4efdf; color: #1a7a4a; }

  /* Footer */
  .report-footer { text-align: center; color: var(--muted); font-size: 0.78rem; padding: 24px; margin-top: 12px; border-top: 1px solid var(--border); }

  /* Stat comparison */
  .stat-compare { display: flex; gap: 24px; flex-wrap: wrap; }
  .stat-item { background: var(--light); border-radius: 8px; padding: 14px 20px; border: 1px solid var(--border); min-width: 120px; }
  .stat-item .s-val { font-size: 1.5rem; font-weight: 800; color: var(--primary); }
  .stat-item .s-label { font-size: 0.74rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.5px; margin-top: 2px; }

  /* Delta indicator */
  .delta-pos { color: var(--accent2); font-weight: 700; }
  .delta-neg { color: var(--danger); font-weight: 700; }
  .delta-neu { color: var(--muted); font-weight: 700; }
</style>
</head>
